using UnityEngine;
namespace Blocklands {public partial class Sandbox
{
    OwnedHome locatedRoom;Transform roomBeacon;
    void RegisterLegacyVillageHome(){if(World.Region!=1||HouseBase.Count==0||saveBlocked)return;foreach(var h in OwnedHomes)if(h.region==1&&!h.realm&&h.x==28&&h.y==14&&h.z==50){h.legacy=true;return;}OwnedHomes.Add(new OwnedHome{region=1,x=28,y=14,z=50,legacy=true});}
    public OwnedHome FindSecretHome(){RegisterLegacyVillageHome();OwnedHome best=null;float distance=float.PositiveInfinity;foreach(var h in OwnedHomes)if(!h.realm&&!InVoidRealms&&h.region==World.Region){float d=Vector3.Distance(Player.transform.position,new Vector3(h.x+5,h.y,h.z+5));if(d<distance){distance=d;best=h;}}return best;}
    public bool LocateSecretRoom(OwnedHome home=null){home=home??FindSecretHome();if(home==null){Notice="这个地区还没有你的房屋。先V建旧小屋，或在工坊自由建房。";return false;}locatedRoom=home;if(roomBeacon!=null)Destroy(roomBeacon.gameObject);var beacon=new GameObject("仅玩家可见的入口定位点").transform;beacon.SetParent(secretRoomRoot,false);beacon.position=new Vector3(home.x+3,home.y+2.1f,home.z+3);var art=beacon.gameObject.AddComponent<RoyalArt>();art.Piece("入口定位光点",Vector3.up*.15f,Vector3.one*.2f,new Color(.55f,1,.83f),PrimitiveType.Sphere);foreach(var t in beacon.GetComponentsInChildren<Transform>())t.gameObject.layer=2;roomBeacon=beacon;Notice="已标出自己家的木板入口；提示只供你定位，不会让村民认出暗门。";return true;}
    public bool GoToSecretEntrance(OwnedHome chosen=null){var h=chosen??FindSecretHome();if(h==null){Notice="先在这个地区建自己的房屋。";return false;}foreach(float x in new[]{4.8f,5.4f,1.1f}){Vector3 p=new Vector3(h.x+x,h.y+2.1f,h.z+3);bool clear=true;foreach(var c in Physics.OverlapCapsule(p+Vector3.up*.32f,p+Vector3.up*1.48f,.28f,~(1<<2),QueryTriggerInteraction.Ignore))if(c!=Player.Body&&c.bounds.max.y>p.y+.01f){clear=false;break;}if(!clear)continue;if(LifeWorkshopOpen)CloseLifeWorkshop();StopSecretSwing();Player.Teleport(p,x>3?270:90,45);LocateSecretRoom(h);Notice=h.secretRoomVersion==1?"已到木板入口旁。看着定位光点下面的木板，轻按H设密码或开门。":"已到旧家入口位置。Esc→生活工坊→自由建房，点修地下密室；旧V房屋免费补齐。";return true;}Notice="入口旁有方块或人物挡着，请先清理通道。";return false;}
        void DrawRoomLocation(float w,float h){if(locatedRoom==null||locatedRoom.region!=World.Region||Paused||SecretMonitorOpen||DeepInputCaptured||InDeepBase)return;Vector3 target=new Vector3(locatedRoom.x+3,locatedRoom.y+2,locatedRoom.z+3);float distance=Vector3.Distance(Player.transform.position,target);if(distance>3)Label(new Rect(w/2-320,h-205,640,30),"我家密室入口 · "+Mathf.RoundToInt(distance)+"米 · 屋内前左侧，坐标 "+Mathf.RoundToInt(target.x)+" / "+Mathf.RoundToInt(target.z),16,new Color(.65f,1,.82f),TextAnchor.MiddleCenter);}
}}
